import React, { useEffect, useMemo, useState } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { AlertTriangle, PackageSearch, RefreshCw, FileWarning } from 'lucide-react';
import api from '@/lib/api';

const FILTERS_DEFAULT = { empresa_id: '', proveedor_id: '', lote: '', semaforo: '' };

function money(value) {
  const n = Number(value || 0);
  return n.toLocaleString('es-MX', { style: 'currency', currency: 'MXN' });
}

function number(value) {
  const n = Number(value || 0);
  return n.toLocaleString('es-MX', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function badgeClass(value) {
  const s = String(value || '').toUpperCase();
  if (s === 'ROJO') return 'bg-red-50 text-red-700 border-red-200';
  if (s === 'AMARILLO') return 'bg-yellow-50 text-yellow-700 border-yellow-200';
  if (s === 'VERDE') return 'bg-green-50 text-green-700 border-green-200';
  return 'bg-zinc-50 text-zinc-700 border-zinc-200';
}

export default function LotesProveedorPage() {
  const [filters, setFilters] = useState(FILTERS_DEFAULT);
  const [rendimientos, setRendimientos] = useState([]);
  const [reclamos, setReclamos] = useState([]);
  const [selected, setSelected] = useState(null);
  const [drilldown, setDrilldown] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [form, setForm] = useState({ motivo: '', descripcion: '', prioridad: 'MEDIA' });

  const query = useMemo(() => {
    const params = new URLSearchParams({ limit: '100', offset: '0' });
    Object.entries(filters).forEach(([key, value]) => { if (value) params.append(key, value); });
    return params.toString();
  }, [filters]);

  async function loadData() {
    setLoading(true);
    setError('');
    try {
      const [rendimientosRes, reclamosRes] = await Promise.all([
        api.get(`/tablajeria/lotes-proveedor/rendimientos?${query}`),
        api.get('/tablajeria/reclamos-proveedor?limit=100')
      ]);
      setRendimientos(rendimientosRes.data?.rendimientos || []);
      setReclamos(reclamosRes.data?.reclamos || []);
    } catch (err) {
      setError(err?.response?.data?.detail || 'No fue posible cargar lotes proveedor.');
    } finally {
      setLoading(false);
    }
  }

  async function openDrilldown(row) {
    setSelected(row);
    setDrilldown(null);
    const id = row.LoteRendimientoID || row.lote_rendimiento_id || row.id;
    if (!id) return;
    try {
      const res = await api.get(`/tablajeria/lotes-proveedor/${id}/drilldown`);
      setDrilldown(res.data);
    } catch (err) {
      setError(err?.response?.data?.detail || 'No fue posible cargar drilldown del lote.');
    }
  }

  async function crearReclamo() {
    const id = selected?.LoteRendimientoID || selected?.lote_rendimiento_id || selected?.id;
    if (!id || !form.motivo) return;
    try {
      await api.post(`/tablajeria/lotes-proveedor/${id}/reclamos`, {
        motivo: form.motivo,
        descripcion: form.descripcion,
        prioridad: form.prioridad,
        evidencia: { origen: 'frontend_tablajeria_lotes_proveedor' }
      });
      setForm({ motivo: '', descripcion: '', prioridad: 'MEDIA' });
      await loadData();
      await openDrilldown(selected);
    } catch (err) {
      setError(err?.response?.data?.detail || 'No fue posible crear reclamo proveedor.');
    }
  }

  useEffect(() => { loadData(); }, [query]);

  return (
    <div className="p-6 space-y-6" data-testid="tablajeria-lotes-proveedor">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold flex items-center gap-2"><PackageSearch className="h-7 w-7" />Lotes proveedor</h1>
          <p className="text-sm text-muted-foreground mt-1">Rendimiento, desviaciones, impacto económico y reclamos por lote de compra.</p>
        </div>
        <Button variant="outline" size="sm" onClick={loadData} disabled={loading}>
          <RefreshCw className={loading ? 'h-4 w-4 mr-2 animate-spin' : 'h-4 w-4 mr-2'} />Actualizar
        </Button>
      </div>

      {error && <div className="p-4 rounded-lg bg-red-50 text-red-700 flex items-center gap-2"><AlertTriangle className="h-5 w-5" />{error}</div>}

      <Card>
        <CardHeader><CardTitle>Filtros</CardTitle><CardDescription>Consulta por empresa, proveedor, lote o semáforo.</CardDescription></CardHeader>
        <CardContent className="grid grid-cols-1 md:grid-cols-4 gap-3">
          <input className="border rounded-md px-3 py-2 text-sm" placeholder="Empresa ID" value={filters.empresa_id} onChange={(e) => setFilters({ ...filters, empresa_id: e.target.value })} />
          <input className="border rounded-md px-3 py-2 text-sm" placeholder="Proveedor ID" value={filters.proveedor_id} onChange={(e) => setFilters({ ...filters, proveedor_id: e.target.value })} />
          <input className="border rounded-md px-3 py-2 text-sm" placeholder="Lote proveedor/interno" value={filters.lote} onChange={(e) => setFilters({ ...filters, lote: e.target.value })} />
          <select className="border rounded-md px-3 py-2 text-sm" value={filters.semaforo} onChange={(e) => setFilters({ ...filters, semaforo: e.target.value })}>
            <option value="">Todos</option><option value="VERDE">Verde</option><option value="AMARILLO">Amarillo</option><option value="ROJO">Rojo</option>
          </select>
        </CardContent>
      </Card>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
        <Card className="xl:col-span-2">
          <CardHeader><CardTitle>Rendimientos por lote</CardTitle><CardDescription>{rendimientos.length} registros visibles</CardDescription></CardHeader>
          <CardContent className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="text-muted-foreground"><tr><th className="text-left p-2">Lote</th><th className="text-left p-2">Proveedor</th><th className="text-right p-2">Rendimiento</th><th className="text-right p-2">Desviación</th><th className="text-right p-2">Impacto</th><th className="text-center p-2">Semáforo</th></tr></thead>
              <tbody>
                {rendimientos.map((row, idx) => (
                  <tr key={row.LoteRendimientoID || idx} className="border-t hover:bg-zinc-50 cursor-pointer" onClick={() => openDrilldown(row)}>
                    <td className="p-2"><div className="font-medium">{row.LoteProveedor || '-'}</div><div className="text-xs text-muted-foreground">{row.LoteInterno || row.FolioOrdenTablaje || '-'}</div></td>
                    <td className="p-2">{row.ProveedorNombre || '-'}</td>
                    <td className="p-2 text-right">{number(row.RendimientoRealPorcentaje)}%</td>
                    <td className="p-2 text-right">{number(row.DesviacionPorcentaje)}%</td>
                    <td className="p-2 text-right">{money(row.ImpactoEconomico)}</td>
                    <td className="p-2 text-center"><span className={`px-2 py-1 rounded border text-xs ${badgeClass(row.Semaforo)}`}>{row.Semaforo || 'SIN_DATOS'}</span></td>
                  </tr>
                ))}
                {!rendimientos.length && <tr><td colSpan="6" className="p-6 text-center text-muted-foreground">Sin registros.</td></tr>}
              </tbody>
            </table>
          </CardContent>
        </Card>

        <Card>
          <CardHeader><CardTitle>Drilldown y reclamo</CardTitle><CardDescription>Compra, recepción, factura, tablajería y seguimiento.</CardDescription></CardHeader>
          <CardContent className="space-y-4 text-sm">
            {!selected && <p className="text-muted-foreground">Selecciona un lote.</p>}
            {selected && <><div><div className="text-xs text-muted-foreground">Proveedor</div><div className="font-medium">{selected.ProveedorNombre || '-'}</div></div><div className="grid grid-cols-2 gap-3"><div><div className="text-xs text-muted-foreground">OC</div>{selected.OrdenCompraFolio || '-'}</div><div><div className="text-xs text-muted-foreground">Recepción</div>{selected.RecepcionFolio || '-'}</div><div><div className="text-xs text-muted-foreground">Factura</div>{selected.FacturaFolio || '-'}</div><div><div className="text-xs text-muted-foreground">Impacto</div>{money(selected.ImpactoEconomico)}</div></div><div className="space-y-2 border-t pt-3"><input className="w-full border rounded-md px-3 py-2" placeholder="Motivo del reclamo" value={form.motivo} onChange={(e) => setForm({ ...form, motivo: e.target.value })} /><textarea className="w-full border rounded-md px-3 py-2" rows="3" placeholder="Descripción" value={form.descripcion} onChange={(e) => setForm({ ...form, descripcion: e.target.value })} /><select className="w-full border rounded-md px-3 py-2" value={form.prioridad} onChange={(e) => setForm({ ...form, prioridad: e.target.value })}><option value="BAJA">Baja</option><option value="MEDIA">Media</option><option value="ALTA">Alta</option><option value="CRITICA">Crítica</option></select><Button onClick={crearReclamo} disabled={!form.motivo} className="w-full"><FileWarning className="h-4 w-4 mr-2" />Abrir reclamo</Button></div><div className="border-t pt-3"><div className="font-medium mb-2">Reclamos del lote</div>{(drilldown?.reclamos || []).map((r) => <div key={r.ReclamoProveedorID} className="border rounded-md p-2 mb-2"><div className="font-medium">{r.FolioReclamo}</div><div className="text-xs text-muted-foreground">{r.Estatus} · {r.Prioridad}</div><div>{r.Motivo}</div></div>)}{drilldown && !drilldown.reclamos?.length && <div className="text-muted-foreground">Sin reclamos.</div>}</div></>}
          </CardContent>
        </Card>
      </div>

      <Card>
        <CardHeader><CardTitle>Reclamos proveedor</CardTitle><CardDescription>Histórico y abiertos.</CardDescription></CardHeader>
        <CardContent className="overflow-x-auto"><table className="w-full text-sm"><thead className="text-muted-foreground"><tr><th className="text-left p-2">Folio</th><th className="text-left p-2">Proveedor</th><th className="text-left p-2">Motivo</th><th className="text-left p-2">Estatus</th><th className="text-right p-2">Impacto</th></tr></thead><tbody>{reclamos.map((r) => <tr key={r.ReclamoProveedorID} className="border-t"><td className="p-2 font-medium">{r.FolioReclamo}</td><td className="p-2">{r.ProveedorNombre || '-'}</td><td className="p-2">{r.Motivo}</td><td className="p-2">{r.Estatus}</td><td className="p-2 text-right">{money(r.ImpactoEconomico)}</td></tr>)}</tbody></table></CardContent>
      </Card>
    </div>
  );
}
